<?php

namespace App\Http\Requests\Admin;

use App\Support\Email;
use Illuminate\Foundation\Http\FormRequest;

class StoreCustomerRequest extends FormRequest
{
    /**
     * Get the validation rules that apply to the request.
     *
     * The account number is generated by the system, and every new account
     * starts ACTIVE with a zero balance (money only enters through a teller).
     * The email is the one the student must sign in with to activate the app.
     *
     * @return array<string, mixed>
     */
    public function rules(): array
    {
        return [
            'nis' => ['required', 'string', 'max:20', 'unique:customers,nis'],
            'full_name' => ['required', 'string', 'max:255'],
            'email' => ['required', 'string', 'email:rfc', 'max:255', 'unique:customers,email'],
            'class' => ['required', 'in:X,XI,XII'],
            'major_id' => ['required', 'integer', 'exists:majors,id'],
            'group' => ['required', 'in:1,2,3,4'],
            // The customer creates the PIN in the app after activation.
            'pin' => ['prohibited'],
        ];
    }

    /**
     * @return array<string, string>
     */
    public function messages(): array
    {
        return ['pin.prohibited' => 'PIN dibuat oleh nasabah di aplikasi Bank Mini setelah aktivasi.'];
    }

    protected function prepareForValidation(): void
    {
        if (is_string($this->input('email'))) {
            $this->merge(['email' => Email::normalize($this->input('email'))]);
        }
    }
}
